text:
{
  "design": {
    "theme": "studio",
    "picture_style": "illustration"
  },
  "flow": [
    {
      "slide": 1,
      "does": "Recall familiar French introductions",
      "look_at": {
        "kind": "picture",
        "shows": "A family together"
      },
      "teaches": []
    },
    {
      "slide": 2,
      "does": "Share the lesson objectives",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": []
    },
    {
      "slide": 3,
      "does": "Teach and identify six family terms",
      "look_at": {
        "kind": "diagram",
        "shows": "A family tree centred on Camille"
      },
      "teaches": [1]
    },
    {
      "slide": 4,
      "does": "Explain how mon, ma and mes match nouns",
      "look_at": {
        "kind": "diagram",
        "shows": "Family nouns grouped by gender and number"
      },
      "teaches": [1]
    },
    {
      "slide": 5,
      "does": "Check possessive choice with a hinge question",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [1]
    },
    {
      "slide": 6,
      "does": "Model name, age and personality sentences",
      "look_at": {
        "kind": "picture",
        "shows": "A friendly brother"
      },
      "teaches": [2]
    },
    {
      "slide": 7,
      "does": "Try a near-identical brother description",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [2]
    },
    {
      "slide": 8,
      "does": "Correct the belief that adjectives never change",
      "look_at": {
        "kind": "picture",
        "shows": "A brother and sister for contrasting descriptions"
      },
      "teaches": [2]
    },
    {
      "slide": 9,
      "does": "Model having and not having siblings",
      "look_at": {
        "kind": "diagram",
        "shows": "A sibling record with one brother and no sisters"
      },
      "teaches": [3]
    },
    {
      "slide": 10,
      "does": "Try a near-identical sibling description",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [3]
    },
    {
      "slide": 11,
      "does": "Combine the structures with a sister profile",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [1, 2, 3]
    },
    {
      "slide": 12,
      "does": "Apply the language to a new family",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [1, 2, 3]
    }
  ],
  "title": {
    "template": "title",
    "heading": "Ma famille",
    "lead": "My family\nDis ton prénom et ton âge.\nSay your name and age in French.",
    "picture": {
      "shows": "an imaginary family spending time together in a park",
      "must_see": [
        "two older adults",
        "two younger adults",
        "three smiling children"
      ],
      "subject": "generic"
    }
  },
  "slides": [
    {
      "template": "big-visual",
      "heading": "Les membres de ma famille",
      "lead": "Montre et dis : qui est qui ? / Point and say: who is who?",
      "figure": {
        "kind": "labelled-diagram",
        "shows": "A family tree centred on Camille, with her brother and sister alongside her, her father and mother above, and her two paternal grandparents above her father. Use a small English gloss beneath each French label. Camille is the speaker.",
        "labels": [
          "Camille : moi / me",
          "mon père / father",
          "ma mère / mother",
          "mon frère / brother",
          "ma sœur / sister",
          "mes parents / parents",
          "mes grands-parents / grandparents"
        ]
      }
    },
    {
      "template": "visual-text",
      "heading": "Mon, ma ou mes ?",
      "lead": "All three mean “my”. Match the French noun, not the person speaking.",
      "points": [
        "mon: masculine singular",
        "ma: feminine singular",
        "mes: plural"
      ],
      "figure": {
        "kind": "table",
        "shows": "The six family nouns grouped by grammatical gender and number",
        "alt": "Mon goes with père and frère; ma with mère and sœur; mes with parents and grands-parents.",
        "title": null,
        "header": ["mon", "ma", "mes"],
        "rows": [
          ["père", "mère", "parents"],
          ["frère", "sœur", "grands-parents"]
        ]
      }
    },
    {
      "template": "hinge",
      "heading": "Choisis la bonne réponse",
      "stem": "Léa says “my brother”. Which is correct?",
      "options": [
        "ma frère",
        "mon frère",
        "mes frère"
      ],
      "correct": 2
    },
    {
      "template": "visual-text",
      "heading": "Décrire mon frère",
      "lead": "Mon frère s’appelle Hugo. Il a douze ans. Il est gentil.",
      "points": [
        {
          "label": "Name",
          "text": "il/elle s’appelle… = his/her name is…"
        },
        {
          "label": "Age",
          "text": "il/elle a… ans = he/she is… years old"
        }
      ],
      "figure": {
        "shows": "an imaginary boy helping a younger child pick up dropped books",
        "must_see": [
          "boy helping child",
          "books on ground",
          "friendly facial expression"
        ],
        "subject": "generic"
      }
    },
    {
      "template": "practice",
      "heading": "À toi : mon frère",
      "questions": [
        "Name: Louis. Write “My brother’s name is Louis”.",
        "Age: 13 (treize). Write his age.",
        "Personality: kind (gentil). Write his personality."
      ],
      "instruction": "Écris trois phrases. / Write three sentences.\nil s’appelle… • il a… ans • il est…",
      "picture": null
    },
    {
      "template": "compare",
      "heading": "L’adjectif change aussi",
      "columns": [
        {
          "label": "Il / he",
          "text": "Il est gentil ou amusant.\nHe is kind or funny.",
          "picture": {
            "shows": "an imaginary brother smiling during a family game",
            "must_see": [
              "smiling teenage boy",
              "colourful board game"
            ],
            "subject": "generic"
          }
        },
        {
          "label": "Elle / she",
          "text": "Elle est gentille ou amusante.\nShe is kind or funny.",
          "picture": {
            "shows": "an imaginary sister smiling during a family game",
            "must_see": [
              "smiling teenage girl",
              "colourful board game"
            ],
            "subject": "generic"
          }
        }
      ]
    },
    {
      "template": "visual-text",
      "heading": "Mes frères et sœurs",
      "lead": "J’ai un frère. Je n’ai pas de sœur.",
      "points": [
        {
          "label": "J’ai…",
          "text": "I have…: un frère / une sœur"
        },
        {
          "label": "Je n’ai pas de…",
          "text": "I don’t have any…: de frère / de sœur"
        }
      ],
      "figure": {
        "kind": "table",
        "shows": "The sibling record that the two model sentences describe",
        "alt": "This speaker has one brother and no sisters.",
        "title": null,
        "header": ["Sibling", "Number"],
        "rows": [
          ["frère", "1"],
          ["sœur", "0"]
        ]
      }
    },
    {
      "template": "practice",
      "heading": "À toi : les frères et sœurs",
      "questions": [
        "Sisters: 1. Write “I have a sister”.",
        "Brothers: 0. Write “I don’t have any brothers”."
      ],
      "instruction": "Écris deux phrases. / Write two sentences.\nJ’ai… • Je n’ai pas de…\nun frère = a brother • une sœur = a sister",
      "picture": null
    },
    {
      "template": "practice",
      "heading": "Décris cette famille",
      "questions": [
        "You have one sister and no brothers. Write two sentences.",
        "Your sister is Zoé, aged 12 (douze). Write her name and age.",
        "She is funny. Write her personality."
      ],
      "instruction": "Écris cinq phrases. / Write five sentences.\nfrère • sœur • il/elle s’appelle… • il/elle a… ans • il/elle est…\ngentil/gentille = kind • amusant/amusante = funny",
      "picture": null
    },
    {
      "template": "practice",
      "heading": "Présente ta famille",
      "questions": [
        "Choose a real or imaginary family. Write what siblings you have and do not have.",
        "Choose one family member. Write their name, age and one personality trait.",
        "Défi / Stretch: add a second family member with a different trait."
      ],
      "instruction": "Écris un petit paragraphe. / Write a short paragraph.\nmon père/frère • ma mère/sœur • mes parents/grands-parents\nj’ai… • je n’ai pas de… • il/elle s’appelle… • il/elle a… ans • il/elle est…\ngentil/gentille • amusant/amusante\n12 = douze • 13 = treize • 40 = quarante",
      "picture": null
    }
  ]
}
